<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Billiards — drag &amp; shoot</title>
<style>
  :root{
    --bg:#12161b; --panel:#1b2129; --ink:#e8eef5; --accent:#59d08a;
  }
  *{box-sizing:border-box}
  html,body{margin:0;padding:0;background:radial-gradient(1200px 700px at 50% 0%,#1d242c,#0c1013);color:var(--ink);
    font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
  #wrap{max-width:960px;margin:0 auto;padding:18px 14px 40px;}
  h1{font-size:19px;letter-spacing:.4px;margin:4px 0 12px;font-weight:650}
