  button:hover{border-color:var(--accent);color:#fff}
  button:active{transform:translateY(1px)}
  #status{font-size:13px;opacity:.8;margin-left:auto}
  .help{background:var(--panel);border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:12px 14px;
    font-size:14px;line-height:1.55;margin:8px 0 0}
