  const c = cueBall();
  if(!c || c.potted) return;
  if(!allStopped()) return;
  shoot(1180, -14);
  if(!running) resume();
});
window.addEventListener('keydown', function(e){
  if(e.key === 'r' || e.key === 'R'){ reset(defaultRack()); if(!running) resume(); }
